import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"旅","description":"高島易斷 - 旅","frontmatter":{"title":"旅","description":"高島易斷 - 旅"},"headers":[],"relativePath":"classics/takashima/056.md","filePath":"classics/takashima/056.md"}'),i={name:"classics/takashima/056.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><h2 id="旅-1" tabindex="-1">旅 <a class="header-anchor" href="#旅-1" aria-label="Permalink to “旅”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>旅：小亨，旅貞吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>旅，羈旅也，人當失其本居，寄跡他鄉，所謂遠適異國，昔人所悲，亦安得曰大亨以正哉！但求得其所依，足以自存，是亦羈旅之“小亨”也。《旅》中之“貞吉”，即在此矣，故曰“旅貞吉。”</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>山上有火，旅。君子以明慎用刑，而不留獄。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>“山上有火”，與《賁》之“山下有火”，相對之文也。《艮》為山，《離》為火，有火焚山之象，野火燒山，過而不留，君子取其象以聽訟，片言即折，故“不留獄”也。明取《離》之照，慎法《艮》之止，執法如山，不可移動也，燭奸如火，無可掩蔽也，以斯用刑，刑無枉矣。卦上互《兌》，《兌》為刑人，故曰“用刑”。反卦《豐》，《豐》象“折獄”，故曰“不留獄”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運未全盛，宜明以察之，慎以防之，即有災害，可隨即解脫。</p><p>○　問營商：宜出外販運，隨來隨售，不可留積。</p><p>○　問功名：火在山上，有光明遠燭之象，升用在即。</p><p>○　問戰徵：須用火攻。</p><p>○　問家宅：慎防火災。</p><p>○　問婚姻：即日可成。</p><p>○　問疾病：是肝火上炎之症，其勢可危，生死在即，宜慎。</p><p>○　問訟事：即日可了。</p><p>○　問行人：即歸。</p><p>○　問六甲：上半月生女，下半月生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居卦之最下，是始為旅人者。“瑣瑣”，小也；“斯”，《爾雅》曰“離也”；“所”，即《詩》“爰得我所”之所，謂居處也，與二三爻曰“次”，四曰“處”，皆為旅舍之地也。“斯其所”者，謂旅行在外，因瑣瑣細故，遂致離其旅處。《序卦》曰，“旅而無所容”，離其所，則必無地可容矣，故“取災”，言其災由自取耳。《傳》推本於“志窮”，以其較量於瑣瑣之故，一有不遂，則離其旅處，不特旅窮而志亦窮矣，窮則招災，故曰“志窮災也”。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：出身既微，行運亦陋，孤身作客，恐難獲利。</p><p>○　問營商：資財微細，生業亦卑，難免災禍。</p><p>○　問功名：雖得亦卑。</p><p>○　問戰徵：按五百人為旅，軍力單薄，有敗無勝。</p><p>○　問家宅：地位委瑣齷齪，必小戶之家也。慎可免災。</p><p>○　問婚姻：《詩》“瑣瑣姻婭，則無膴仕”，知非名門大族也。</p><p>○　問疾病：有小災悔，初起可治。</p><p>○　問六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《旅》之《離》。</p><p>斷曰：旅，羈旅也，為遠出他鄉，孤身隻影，羈旅無親。爻象以柔為吉，以剛為兇，蓋惟柔順和眾，斯不為孤立也。初爻為初次行旅，“瑣瑣”，小也，為量淺陋，鎦銖必較，以是取災，災由自取耳。今足下佔氣運，得此爻辭，夫人生如寄，天地本逆旅也，散財和眾，則四海皆兄弟，斂財取怨，則坦途成荊棘。人苟委瑣齷齪，逐逐為利，勢將無地容身，所謂“旅而無所容”也，災禍之來，必難免矣。足下宜大度寬容，無吝財，無招怨，和悅處世，所謂“言忠信，行篤敬，雖蠻貊可行”焉。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“即”者，就也；“次”者，舍也；“資”者，貨也。幼者童，壯者僕，《艮》為童僕，故曰“童僕”。《離》為資斧，故曰懷資。二爻柔中居正，有“即次”之象。以虛承實；有懷資之象；柔順，則童僕亦盡其忠信，三事皆得其便宜。內不失己，而己無不安，外不失人，而人無不與，皆由柔順中正之德所致也，故曰“旅即次，懷其資，得童僕貞”。不言吉者，旅寓之際，得免災厲為幸耳。《象傳》之意，亦不外此也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：有財有人，運途中正，自無憂也。</p><p>○　問營商：得財則可以謀利，得人則可以共事，千里作客，可以無憂矣。</p><p>○　問功名：是以財捐納者。</p><p>○　問戰徵：資財，即軍餉也，“童僕”，即軍卒也，餉足兵強，攻無不克。</p><p>○　問家宅：必是寄居之宅，喜得財用充裕，童從順正，家室和平，自無咎禍也。</p><p>○　問婚姻：有富室贅婿之象。</p><p>○　問疾病：旅處得病，喜有童僕，盡心服侍，可以調養痊癒。</p><p>○　問六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十七年，餘漫遊九州，一日往觀某石灰坑，其夜有社員過訪予寓，曰：君精於幹事，今日巡視敝坑，定有高見，幸請教示。餘曰：炭坑之業，餘素所未諳，辱承諸君下問，敢為一佔以決之。筮得《旅》之《鼎》。</p><p>斷曰：本社在東京出店，遠隔九州，營謀坑業，諸君皆行旅在外者也，故曰“旅即次，懷其資，得童僕貞”。知此坑業，有財有人，可大可久，其所經辦，上下用人，皆正直無私，本可無憂矣。但三爻有焚次喪僕之象，明年防有火災；四爻曰“得其資斧”，後年可以獲利，償斯所失；五爻小失大得，坑業聲名，得以上達，是為坑務全盛之時；惜上爻曰“鳥焚其巢，先笑後號咷”，此象可慮，約應在五年之內也，宜預為慎防。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三爻處內卦之極，出《艮》入《離》，《離》為火，故有焚象；《艮》為居，為舍，“次”，旅舍也，故曰“焚其次”。童僕隨侍於次者，次焚，而童僕亦喪，是背主而去者也。《艮》為童僕，故曰“喪其童僕”。旅次焚，禍起不測，有由童僕之不戒者，亦有不由於童僕者。三爻“童僕貞”，然雖貞亦危，故曰“貞厲”。旅次經焚，身危資失，旅客固受傷矣，而在童僕，向承使令，一經焚災，深恐主人責問，舍此而去，亦其義也，故《象傳》兩釋之。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：運途顛倒，破敗重重，大為可危。</p><p>○　問戰徵：謹防火攻，尤慮軍心渙散，不戰自遁。</p><p>○　問營商：防有不測之禍，可危。</p><p>○　問功名：目下難望，必二年後，至五爻曰“終以譽命”，可以成名矣。</p><p>○　問婚姻：一時不成，難偕其老。</p><p>○　問家宅：防有祝融之災。</p><p>○　問疾病：本人可愈，兒女或童僕，難以保全。</p><p>○　問失物：必是童僕所竊。</p><p>○　問六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>真言宗高僧雲照律師，博識釋風俗，為一宗之覺士也，餘昔遊高野西京，時得相晤。明治十八年夏初，雲照師偶訪餘廬，謂餘曰：貧衲以虛無為宗，吉凶悔吝，無復掛念，所以眷眷不忘者，惟在宗教之盛衰耳，敢煩一佔。筮得《旅》之《晉》。</p><p>斷曰：夫《旅》親寡之卦也，在禪家離凡脫俗，身入空門，以四大為禪房，以六道為逆旅，凡一生所涉，悔吝吉凶，悉屬幻境而已。今律師佔宗教盛衰，得《旅》三爻，在律師脫離本山，雲遊世外，到處天涯，何有旅舍？隨身衣缽，何有童僕？八妄皆空，無所謂貞也；九根無礙，無所謂厲也；三昧之火既消，無所焚也；四禪之縛既脫，無所喪也。爻象所示，不足為律師掛慮。按《旅》三變而為《晉》，《晉》《彖傳》曰“晉，進也，明出地上”，《離》者，日也，象如佛日長明，照大地。禪門之宗教，當有日進日盛之象，是可為律師慶也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四居《離》之始，《離》為見，四之旅行，是往而求利見也。得位進於朝，不得則旅於處，故《傳》曰“未得位也”。《離》為資斧，故曰“資斧”，即《春秋傳》所謂“居則具一日之積，行則備一夕之衛”是也。資與二懷資不同，二之資，由我而具，四之資，自外而來，故曰“得”。《離》為干戈，有斧象，斧所以為衛也。四之所以僕僕行旅者，惟期得位乘時耳，乃所得而僅在資斧，所願未償，故“我心不快”也。以四初入《離》爻，文采未彰，名譽未顯，故祿位猶末得也。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：盛運未至，所得亦僅耳。</p><p>○　問營商：出外販運少有獲利，未能滿望。</p><p>○　問功名：一時未得，容待來年，定可成就也。</p><p>○　問戰徵：可以擄得敵糧，未能遽獲大勝。</p><p>○　問婚姻：嫁資頗厚，但是偏房，非正嫡也。</p><p>○　問家宅：地位不當。</p><p>○　問疾病：是心疾也，因謀望不遂，憂鬱所致。</p><p>○　問失物：可得。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治十八年某月，某貴顯來訪，曰：餘知友某氏，今受外國公使之命，在某氏尚別有希望，不知成否？請勞一筮。筮得《旅》之《艮》。</p><p>斷曰：《旅》者出內向外之卦，出使外國，即旅行之象。凡使臣遠適異國，行則授餐，宿則授館，固其宜也，故曰“旅於處，得其資斧”。至舍使任而別謀位置，是得隴望蜀，恐未能如願以償，宜其中心不快也。迨五爻曰“終以譽命”，則所謀可遂矣。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五爻柔順文明，為《離》之主，《離》為雉，又為弓矢，故取象“射雉”。五動體《乾》，矢動雉飛，故“一矢亡”。五自《坤》三來，《坤》為終，《離》為譽，下互《巽》，《巽》為命，故曰“終以譽命”。古者士以雉為贄，射雉而得，是士之進身有階也。五以遠適他邦，得以射雉著能，一時翕然稱美，名譽上聞，而來賜命之慶也。故《傳釋》之曰：“上逮也。”</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：運途柔順，小往大來，終有慶也。</p><p>○　問營商：雖小失，有大得也，名利兼全。</p><p>○　問功名：晚運亨通，聲名上達。</p><p>○　問戰徵：有一翦成功之象。</p><p>○　問家宅：翬飛鳥革，善美堪稱。</p><p>○　問婚姻：二五得應，世稱佳偶。</p><p>○　問疾病：想是身臨矢石，以忠殉難，得有賜命之榮。</p><p>○　問六甲：有桑弧蓬矢之兆，男喜也。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>明治二十四年，佔某貴顯氣運，筮得《旅》之《遁》。</p><p>斷曰：五處文明之爻，雉，鳥之有文者也，故“離為雉”；射雉得之，言能取法文明也。矢發於近，及於遠，有《旅》之象；一矢雖亡，一雉可獲，小費大得，宜其志譽上聞也。今貴下佔氣運，得此爻，就卦象論，知貴下有奉命遠遊之象；就爻辭論，知貴下有小往大來之慶。自維新以來，國家政令，多取法歐美，今貴下皇華奉使，遠適異國，一以敦兩邦之好，一以觀上國之風，彼所謂日進文明者，何難一舉而得之？譬如射雉，可一矢而中的矣。則貴下之聲譽，可遠播於四方，貴下之使命，定榮邀夫三賜。是可為貴下預賀焉。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>《離》為鳥，《艮》為止，故曰“巢”。《離》為火，互《巽》為木，故曰“焚其巢”。鳥之有巢，猶《旅》之有次也，三居內卦之極，剛而過中，故其次焚；上居全卦之極，高而忘危，故其巢亦焚，辭雖不同，其義一也。三至五互《兌》，《兌》為悅，為口，有笑之象；《離》五曰“出涕沱若”，有號咷之象。先互《兌》，後入《離》，故曰“先笑後號咷”。《離》本《坤》體，《坤》為牛，亦為喪，故曰“喪牛”。牛性最順，《旅》卦全體，以柔順者吉，剛暴者兇，上以剛處極，失其順矣，是謂“喪牛”。“易”，不難也；喪其牛，勢必兇矣。《象傳》以《旅》處上極，猶如《離》木上槁，故曰“其義焚也”。“終莫之聞”者，“喪牛於易”，猶客死於外，無室無家，終無人過而問之者矣。《大壯》曰“喪羊”，喪其狠也；《旅》曰“喪牛”，喪其順也。狠可喪，順不可喪也。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：行運已極，高而無與，樂極悲來，兇之道也。</p><p>○　問戰徵：防有焚營劫寨之危。</p><p>○　問營商：先小利，後大損，兇災疊至，可危可危。</p><p>○　問功名：有喪無得。</p><p>○　問家宅：有覆巢累卵之危。</p><p>○　問婚姻：先成後散，先喜後悲，兇。</p><p>○　問疾病：屬牛者必兇。</p><p>○　問六甲：生女，不育。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治廿四年五月，餘遊寓大孤，一日侵曉，有新聞記者數人，訪餘旅舍，曰：今回有一大事變，請為一佔。餘詢為何事，曰大津事變也。筮得《旅》之《小過》。</p><p>斷曰：卦名曰《旅》，無論為名為利，或貴或賤，凡北馬南船，邀遊天涯，皆旅人也。旅人馳逐風塵，猶鳥之翱翔雲霄，鳥之棲集有巢，旅之止宿有所，其義同也。上居高位，有貴人之象；高而可危，有焚巢之慮。巢之未焚，安棲可喜，巢之既焚，失所可悲，故有“先笑後號咷”之辭。牛所以駕車而行也，“焚其巢”，既不得其棲；喪其牛，又不便於行，不幾倀倀無之矣！佔大津事變，得《旅》上爻，上爻處《艮》之極，《艮》反為《震》，《震》為主器，有太子之象；上爻又在位外，有太子出遊在外之象。《離》為火，火炎上，巢於樹上，故象為“鳥焚其巢”，是巢之焚，以高而在上取兇也。今番大津之變，亦因俄為強國，太子又在高位，是以有此非常之禍。《離》又為刀，故傷為刀擊，傷在頭部，亦應上爻。當俄太子始來我國，禮遇之豐，彼此歡洽，忽罹此變，彼此驚歎，即所謂“先笑後號咷”也。是日俄太子游至大津，意在輕車簡易，不駕輿衛，不知此一擊也，正因其易而來，故曰“喪牛於易”。《離》為牛，故取象於牛；《離》又為甲，聞太子之帽，中有鐵甲，故無重傷。卦至上已終，出卦為《巽》，《巽》為歸，知太子必即罷遊歸國矣。《象傳》曰“終莫之聞”，料知太子無恙歸國，在俄國亦以狂暴目之，置之不聞而已。至兇犯津田三藏之罪，《旅》《大象》曰，“君子以明慎用刑，而不留獄”，當以速決無疑。餘明晰以斷，新聞記者鹹皆驚服。此佔為關兩國交際，未許刊揭報紙，謹錄以呈扈從諸大臣。後見大阪《朝日新聞》報刊載副島伯所論，謂津田兇犯，宜速處決，此言正合《易》旨也。</p>',107)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
